// oh-my-pi's trailing-selector grammar, archive inner paths, and SQLite
// targets — one path grammar keeps the tool count flat)
// ---------------------------------------------------------------------------

/// Default entry cap for archive directory listings (omp's
/// `#readArchiveDirectory` DEFAULT_LIMIT).
const defaultArchiveListLimit = 500;

/// Assembles the `read` tool description: the base prompt with its size
/// tokens substituted, plus the SQLite section ([readSqliteSectionPrompt])
/// only when the host provides a [sqlite] engine. The substituted value
/// carries the section's surrounding blank lines (`parseFrontmatter` trims
/// them from the section file), so gating it out leaves exactly one blank
/// line between the Archives and Hashline mode sections.
String _readDescription({SqliteEngine? sqlite}) {
  return readToolDescriptionPrompt
      .replaceAll('{{maxLines}}', '$defaultToolMaxLines')
      .replaceAll('{{maxBytesKb}}', '${defaultToolMaxBytes ~/ 1024}')
      .replaceAll(
        '{{sqlite}}',
        sqlite == null ? '' : '\n\n$readSqliteSectionPrompt',
      );
}

/// Creates the `read` tool: reads a text file or image with optional `offset`
/// (1-indexed) and `limit`, truncating text output to [defaultToolMaxLines]
/// lines or [defaultToolMaxBytes] bytes with an actionable continuation notice.
/// Images are decoded, optionally resized to the inline dimension/byte limits,
/// and returned as base64 content.
///
/// The path may carry a trailing selector (oh-my-pi's grammar, ported in
/// `read_selector.dart`): `:N` / `:A-B` / `:A+C` line ranges, comma-merged
/// multi-ranges (`:5-16,960-973`), and `:raw` verbatim output — alone or
/// combined with a range in either order (`:raw:50-100`). A single range maps
/// onto the offset/limit pipeline; multi-ranges render one block per range
/// joined by an elision separator, with out-of-bounds ranges reported as
/// skipped notices. `:raw` suppresses line numbers, the hashline header, and
/// all continuation notices. The `offset`/`limit` arguments keep working and
/// must not be combined with a selector.
///
/// Two extended targets consume their own colon syntax behind the same tool:
///
/// - Archive inner paths (`archive.zip:inner/entry`, also `.tar` and
///   `.tar.gz`/`.tgz`, via `archive_reader.dart`): the member's text runs
///   through the same pipeline (selectors apply after extraction); a bare
///   archive path or inner directory lists its contents, and binary entries
///   yield a note instead of bytes.
/// - SQLite databases (`data.db`, `data.db:table`, `data.db:table:key`,
///   `data.db:table?limit=…&offset=…&order=…&where=…`, `data.db?q=SELECT …`,
///   via `sqlite/sqlite_reader.dart`): rendered as width-capped ASCII
///   tables. Only available when the host provides a [SqliteEngine] (FFI,
///   exported from `lib/io.dart`); without one the read returns a clean
///   "not supported" note — what web hosts get. The tool description
///   mirrors that gating: without an engine the SQLite section is omitted.
///
/// With `hashline: true` (omp's hashline display mode), text output lines are
/// prefixed with their 1-indexed line number (`N:text`) and the output is
/// preceded by a `[path#TAG]` header carrying the whole-file content-hash
/// tag; the full file text plus the displayed line range are recorded in
/// [snapshots] so `edit` patches can anchor against them. Ranged reads keep
/// real file line numbers. Default is `false` (omp defaults it on; we keep
/// the legacy plain output as the default so existing read consumers are
/// unaffected — the `edit` tool description tells the model to opt in when
/// it intends to edit by anchors).
///
/// When [model] is provided, image results carry an extra note when the
/// current model has no `image` input (pi's `getNonVisionImageNote`); the
/// image itself stays in the result — providers substitute an explicit
/// placeholder at request time (see `downgradeUnsupportedImages`).
///
/// Built-in skill reads (issue #1151, extended by gh-1444): a `builtin://`
/// path resolves from the embedded copy before any filesystem access, and a
/// failed read of a path whose sibling `<path>.pointer` exists follows the
/// pointer — but only to a `builtin://skills/<name>/SKILL.md` target
/// matching the pointer's own directory ([followSkillPointer]); any other
/// pointer target is refused loudly. A builtin resource that resolves EMPTY
/// is retried once and then fails with an explicit error naming the
/// resource (gh-1444 AC2/E5) — never a silent empty success. [builtinText]
/// overrides the embedded-text lookup (the AC2 fault-injection seam for
/// tests); production callers omit it.
/// gh-1444 AC2: a builtin resource that resolves EMPTY is retried once,
/// then fails loudly naming the resource — an empty payload on a
/// non-empty resource is never a silent success. [builtinText] overrides
/// the embedded-text lookup (the AC2 fault-injection seam for tests);
/// production callers omit it.
String? _resolveBuiltinText(
  String path,
  String? Function(String path)? builtinText,
) {
  var embedded = (builtinText ?? builtinSkillTextAt)(path);
  if (embedded != null && embedded.isEmpty) {
    embedded = (builtinText ?? builtinSkillTextAt)(path);
    if (embedded == null || embedded.isEmpty) {
      throw StateError(
        'read $path: builtin resource resolved empty after retry — '
        'the compiled-in skill content is missing; report this as a '
        'harness defect',
      );
    }
  }
  return embedded;
}

AgentTool readFileTool(
  ExecutionEnv env, {
  HashlineSnapshotStore? snapshots,
  Model? Function()? model,
  SqliteEngine? sqlite,
  String? Function(String path)? builtinText,
}) {
  final store = snapshots ?? HashlineSnapshotStore();
  return AgentTool(
    name: 'read',
    label: 'read',
    tier: ApprovalTier.read,
    description: _readDescription(sqlite: sqlite),
    parameters: const {
      'type': 'object',
      'properties': {
        'path': {
          'type': 'string',
          'description':
              'Path to the file to read (relative or absolute). May end '
              'with a trailing selector such as :50-100 or :raw, address an '
              'archive member (archive.zip:inner/file), or address a SQLite '
              'database (data.db:table?limit=20)',
        },
        'offset': {
          'type': 'integer',
          'description': 'Line number to start reading from (1-indexed)',
        },
        'limit': {
          'type': 'integer',
          'description': 'Maximum number of lines to read',
        },
        'hashline': {
          'type': 'boolean',
          'description':
              'Prefix each line with its line number and prepend a '
              '[path#TAG] content-hash header for anchoring hashline edit '
              'patches (default: false)',
        },
      },
      'required': ['path'],
    },
    execute: (arguments, cancelToken, onUpdate) async {
      cancelToken?.throwIfCancelled();
      final rawPath = arguments['path'] as String;
      final offset = (arguments['offset'] as num?)?.toInt();
      final limit = (arguments['limit'] as num?)?.toInt();
      final hashlineMode = (arguments['hashline'] as bool?) ?? false;

      // Peel a trailing selector off the path (omp's grammar). A literal file
      // whose name ends in a selector-shaped tail (`test:1-2`) wins over the
      // selector interpretation.
      final split = await splitPathAndSelPreferringLiteral(rawPath, env);
      final parsed = parseSel(split.sel);
      // Issue #862: a selector already pins the window, so offset/limit are
      // ignored with a notice instead of hard-rejecting the call.
      final windowNotice = readWindowCoercionNotice(
        hasSelector: parsed is! ReadSelectorNone,
        offset: offset,
        limit: limit,
      );

      final extended = await _readExtendedTarget(
        env,
        rawPath,
        split,
        sqlite,
        cancelToken,
      );
      if (extended != null) return _withNotice(extended, windowNotice);

      final path = split.path;
      // Built-in skills (issue #1151): builtin:// paths resolve from the
      // embedded copy before any filesystem access.
      final embedded = _resolveBuiltinText(path, builtinText);
      if (embedded == null) {
        final binaryRead = await env.readBinaryFile(path);
        if (binaryRead.isErr) {
          // gh-1444 AC1: a skill pointer sibling (<path>.pointer) resolves
          // the read onto the compiled-in builtin body — the seeded
          // `.fah/skills/<name>/SKILL.md.pointer` files become transparent.
          // A present-but-invalid pointer is refused loudly (E1); no
          // pointer keeps the original error.
          final followed = await followSkillPointer(
            path,
            (pointerPath) async =>
                (await env.readTextFile(pointerPath)).valueOrNull,
          );
          switch (followed) {
            case SkillPointerResolved(:final text):
              return _withNotice(
                await _readTextContent(
                  env,
                  store,
                  path,
                  parsed,
                  offset,
                  limit,
                  text,
                  hashlineMode,
                  cancelToken,
                ),
                windowNotice,
              );
            case SkillPointerRefused(:final reason):
              throw StateError('read $path: skill pointer refused: $reason');
            case SkillPointerAbsent():
              throw StateError('${binaryRead.errorOrNull}');
          }
        } else {
          final bytes = binaryRead.valueOrNull!;
          cancelToken?.throwIfCancelled();

          final imageResult = _readImageResult(path, bytes, parsed, model);
          if (imageResult != null) {
            return _withNotice(imageResult, windowNotice);
          }
        }
      }

      return _withNotice(
        await _readTextContent(
          env,
          store,
          path,
          parsed,
          offset,
          limit,
          embedded,
          hashlineMode,
          cancelToken,
        ),

/// Vision-image inspection tool (`inspect_image`) for [AgentCli].
///
/// Shaped after the pi extension [pi-inspect-image](https://github.com/TanJeeSchuan/pi-inspect-image):
/// a dedicated vision-capable model analyses a local image and returns a text
/// description. Keeping the image payload out of the main chat context means
/// the primary model does not need vision support — only the derived text
/// enters the conversation.
library;

import 'dart:async';
import 'dart:convert';
import 'dart:typed_data';

import 'package:http/http.dart' as http;

import '../agent/agent_loop.dart' show ToolExecutionResult;
import '../agent/agent_tool.dart';
import '../approval/approval.dart';
import '../context.dart';
import '../env/execution_env.dart';
import '../event_stream.dart';
import '../model.dart';
import '../prompts/prompts.g.dart';
import '../providers/copilot.dart';
import '../providers/copilot_oauth.dart';
import '../providers/openai_completions.dart';
import '../types.dart';

/// The named refusal for the Codex kind (gh-760): the Responses adapter
/// has no vision wire. One constant so the two refuse sites (default
/// endpoint pick and the explicit-baseUrl stream route) cannot drift.
StateError _codexVisionRefusal() => StateError(
      'inspect_image: provider kind "chatgpt-codex" (ChatGPT Codex) has no '
      'vision adapter — configure inspect_image with an openai-completions '
      'or copilot vision model',
    );

/// Configuration for the [inspectImageTool] vision model.
final class InspectImageConfig {
  /// Creates a configuration.
  const InspectImageConfig({
    required this.modelId,
    required this.apiKey,
    this.baseUrl,
    this.maxTokens = 4096,
    this.providerKind = 'openai-completions',
    this.httpClient,
  });

  /// Vision model id, e.g. `gpt-4o` or `openai/gpt-4o`.
  final String modelId;

  /// API key for the vision provider.
  final String apiKey;

  /// Optional base URL. When omitted the provider's default is used
  /// (OpenAI: https://api.openai.com/v1, Copilot:
  /// https://api.githubcopilot.com).
  final String? baseUrl;

  /// Maximum tokens for the vision description.
  final int maxTokens;

  /// Provider adapter kind. `openai-completions` (OpenAI, OpenRouter, and
  /// any OpenAI-compatible endpoint) and `copilot` (GitHub token exchanged
  /// for the short-lived Copilot API token via [streamCopilot]) are
  /// supported today.
  final String providerKind;

  /// Optional HTTP client for testing.
  final http.Client? httpClient;
}

/// Builds the [Model] descriptor used for the vision call.
Model _visionModel(InspectImageConfig config) {
  final baseUrl =
      config.baseUrl ??
      switch (config.providerKind) {
        'copilot' => copilotIndividualBaseUrl,
        // gh-760: the Codex Responses adapter has no vision wire — refuse
        // with a named error instead of silently misrouting the call to
        // api.openai.com via the catch-all below.
        'chatgpt-codex' => throw _codexVisionRefusal(),
        _ => 'https://api.openai.com/v1',
      };
  return Model(
    id: config.modelId,
    name: config.modelId,
    api: 'openai-completions',
    provider: config.providerKind,
    baseUrl: baseUrl,
    input: const ['text', 'image'],
    contextWindow: 128000,
    maxTokens: config.maxTokens,
  );
}

/// Streams the vision request for [config]'s provider kind. Copilot rides
/// the same SSE completions wire through [streamCopilot] (token exchange +
/// mandatory Copilot headers); every other supported kind speaks plain
/// openai-completions.
AssistantMessageEventStream _streamVisionResponse(
  InspectImageConfig config,
  Model model,
  Context context,
) {
  switch (config.providerKind) {
    case 'openai-completions':
      return streamOpenAICompletions(
        model,
        context,
        OpenAICompletionsOptions(
          apiKey: [REDACTED:Sensitive-Value],
          maxTokens: config.maxTokens,
        ),
        config.httpClient,
      );
    case 'copilot':
      return streamCopilot(
        model,
        context,
        CopilotOptions(githubToken: config.apiKey),
        config.httpClient,
      );
    case 'chatgpt-codex':
      // Named refusal (gh-760): the Codex Responses adapter has no vision
      // wire; reaching the old `default` here meant the call had already
      // been misrouted to api.openai.com by _visionModel.
      throw _codexVisionRefusal();
    default:
      throw StateError(
        'Unsupported inspect_image provider kind: ${config.providerKind}',
      );
  }
}

/// Collects the final assistant text out of a vision event stream; throws on
/// a stream error.
Future<String> _collectVisionText(AssistantMessageEventStream stream) async {
  String? text;
  String? error;
  await for (final event in stream) {
    if (event is TextDeltaEvent || event is DoneEvent) {
      final message = event.partial;
      final currentText = message.content
          .whereType<TextContent>()
          .map((b) => b.text)
          .join();
      if (currentText.isNotEmpty) text = currentText;
    } else if (event is ErrorEvent) {
      error = event.error.errorMessage ?? 'unknown error';
    }
  }

  if (error != null) {
    throw StateError('Vision model error: $error');
  }
  return text?.trim() ?? '';
}

/// Streams a vision request and returns the final assistant text.
Future<String> _inspectWithVisionModel(
  InspectImageConfig config,
  Uint8List bytes,
  String mimeType,
  String userPrompt,
) async {
  final model = _visionModel(config);
  final image = ImageContent(data: base64Encode(bytes), mimeType: mimeType);
  final context = Context(
    systemPrompt: inspectImageVisionSystemPrompt,
    messages: [
      UserMessage(
        content: [
          TextContent(
            text: userPrompt.isEmpty ? 'Describe this image.' : userPrompt,
          ),
          image,
        ],
        timestamp: DateTime.now(),
      ),
    ],
  );

  final stream = _streamVisionResponse(config, model, context);
  return _collectVisionText(stream);
}

/// Creates the `inspect_image` tool.
///
/// Parameters:
/// - `path` (string, required): path to the image file.
/// - `prompt` (string, optional): specific question or instructions.
AgentTool inspectImageTool(ExecutionEnv env, InspectImageConfig config) {
  return AgentTool(
    name: 'inspect_image',
    label: 'inspect_image',
    tier: ApprovalTier.read,
    description:
        'Analyze a local image file using a dedicated vision-capable model. '
        'Returns a text description; the image itself does not enter the main '
        'chat context. Supported formats: PNG, JPEG, GIF, WebP, BMP.',
    parameters: const {
      'type': 'object',
      'properties': {
        'path': {
          'type': 'string',
          'description': 'Path to the image file (relative or absolute)',
        },
        'prompt': {
          'type': 'string',
          'description': 'Optional specific question or instructions',
        },
      },
      'required': ['path'],
    },
    execute: (arguments, cancelToken, onUpdate) async {
      cancelToken?.throwIfCancelled();
      final path = arguments['path'] as String;
      final prompt = (arguments['prompt'] as String?) ?? '';

      final read = await env.readBinaryFile(path);
      if (read.isErr) {
        throw StateError('${read.errorOrNull}');
      }
      final bytes = read.valueOrNull!;
      cancelToken?.throwIfCancelled();

      // Detect MIME type from magic bytes. Only the supported image formats
      // are accepted; the actual vision request will re-encode/rescale if
      // needed on the provider side.
      final mimeType = _detectImageMimeType(bytes);
      if (mimeType == null) {
        throw StateError('Unsupported image format or not an image: $path');
      }

      final description = await _inspectWithVisionModel(
        config,
        bytes,
        mimeType,
        prompt,
      );
      return ToolExecutionResult(content: [TextContent(text: description)]);
    },
  );
}

/// Magic-byte signatures of the image formats the tool claims to support,
/// checked in order.
const _imageMagicSignatures = [
  ('image/png', <int>[0x89, 0x50]),
  ('image/jpeg', <int>[0xFF, 0xD8]),
  ('image/gif', <int>[0x47, 0x49, 0x46]),
  ('image/webp', <int>[0x52, 0x49]), // RIFF
  ('image/bmp', <int>[0x42, 0x4D]),
];

/// Whether [bytes] starts with the [magic] signature.
bool _matchesMagicBytes(Uint8List bytes, List<int> magic) {
  for (var i = 0; i < magic.length; i++) {
    if (bytes[i] != magic[i]) return false;
  }
  return true;
}

/// Minimal MIME detection for the image formats the tool claims to support.
String? _detectImageMimeType(Uint8List bytes) {
  if (bytes.length < 8) return null;
  for (final (mimeType, magic) in _imageMagicSignatures) {
    if (_matchesMagicBytes(bytes, magic)) return mimeType;
  }
  return null;
}

/// Heuristic vision detection for free-form hosted model ids.
///
/// Most OpenAI-compatible endpoints expose no modality metadata, so the
/// agent's `Model` would otherwise stay at the provider default `input:
/// ['text', 'image']` (claiming vision for text-only deployments) — or, in
/// the app, `input: ['text']` (blinding vision models). pi/oh-my-pi
/// populate `input` from provider metadata; where none exists this matcher
/// covers the well-known vision model families. A wrong `true` costs a
/// provider-side rejection of an image message (the model still works for
/// text); a wrong `false` makes the model blind — so the list errs on the
/// inclusive side for mainstream hosted models only.
///
/// Shared by the CLI (model pickers, `/model` switches) and the Flutter app
/// (`packages/fa_ui` re-exports this file) — one marker list for both.
library;

/// Vision-capable model families, matched case-insensitively against the
/// model id (including any `provider/` prefix OpenRouter adds).
const _visionMarkers = <String>[
  // OpenAI omni/reasoning families.
  'gpt-4o',
  'gpt-4.1',
  'gpt-4-turbo',
  'gpt-5',
  'chatgpt-4o',
  // Anthropic — every Claude 3+ is multimodal.
  'claude-3',
  'claude-4',
  'claude-sonnet',
  'claude-opus',
  'claude-haiku',
  // Google — all Gemini chat models are multimodal.
  'gemini-',
  // Moonshot — the Kimi lines declare `supports_image_in` on /models
  // (kimi-for-coding, k3/k3-256k, moonshot-v1-*-vision). Bare k2/k3 match
  // anything containing them — the list errs on the inclusive side by design.
  'kimi',
  'moonshot',
  'k3',
  'k2-',
  // Qwen vision lines.
  'qwen-vl',
  'qwen2-vl',
  'qwen2.5-vl',
  'qvq',
  // Mistral vision lines.
  'pixtral',
  'mistral-small-3',
  'ministral',
  // Meta multimodal lines.
  'llama-3.2-11b',
  'llama-3.2-90b',
  'llama-4',
  // Community vision families.
  'llava',
  'moondream',
  'minicpm-v',
  'mini-cpm-v',
  'glm-4v',
  'glm-4.5v',
  'glm-4.6v',
  // GLM-5: only the `...v` lines take image input — plain glm-5/5.1/5.2/
  // 5.3 (and -flash) are text-only on z.ai and OpenRouter metadata alike
  // (issue #42: z.ai 400 `messages.content.type is invalid, allowed
  // values: ['text']` after a /model switch onto glm-5.3).
  'glm-5v',
  // The -flash lite line stays multimodal while the flagship is text-only
  // (OpenRouter input_modalities: glm-5.3-flash ['text','image','video'] vs
  // glm-5.3 ['text']).
  'glm-5.3-flash',
  'internvl',
  'cogvlm',
  'phi-3.5-vision',
  'phi-4-multimodal',
  // xAI.
  'grok-2-vision',
  'grok-4',
  // Gemma 3 multimodal sizes (the 1b is text-only).
  'gemma-3-4b',
  'gemma-3-12b',
  'gemma-3-27b',
];

/// Ids that match a marker above but are known text-only deployments.
const _textOnlyMarkers = <String>['embedding', 'gemma-3-1b'];

/// Whether [modelId] looks like a vision-capable hosted model.
bool modelIdSuggestsVision(String modelId) {
  final id = modelId.toLowerCase();
  if (id.isEmpty) return false;
  if (_textOnlyMarkers.any(id.contains)) return false;
  if (id.contains('vision')) return true;
  return _visionMarkers.any(id.contains);
}

/// The short picker marker for [modelId]'s vision support — shown next to
/// model ids in the CLI model pickers.
String visionMarker(String modelId) =>
    modelIdSuggestsVision(modelId) ? '✓ vision' : '✗ text-only';

/// The input modalities for [modelId] per the heuristic — used when
/// switching to a model the endpoint reported no metadata for.
List<String> inputModalitiesFor(String modelId) =>
    modelIdSuggestsVision(modelId) ? const ['text', 'image'] : const ['text'];

/// truncate everything (issue #1074).
const _unboundedMaxLines = 0x4000000000000000;

/// Transient-failure retries for foreground bash runs: timeout-class
/// failures (a hung transport, or the model's own per-call cap) are
/// retried up to this many times — 3 attempts total — before the error
/// surfaces. Aborts and real command failures never retry.
const bashToolMaxRetries = 2;

/// Backoff between bash retry attempts.
const _bashRetryBackoff = Duration(seconds: 1);

/// Output-silence window before a pending password-ask match fires the
/// sheet (issue #367); parameterized for tests.
const _bashPasswordQuiet = Duration(milliseconds: 250);

/// Creates the four built-in tools ([readFileTool], [writeFileTool],
/// [listDirTool], [shellTool]) bound to [env].
///
/// [snapshots] is the session-scoped hashline snapshot store shared by the
/// `read` and `edit` tools: hashline-mode reads mint the content tags that
/// hashline edit patches cite, and edits mint fresh tags for follow-ups.
/// Defaults to a fresh store — one per [builtinTools] call, i.e. one per
/// agent session.
///
/// When [webSearch] is provided, the `web_search` and `web_fetch` tools are
/// registered with it (provider chain resolved from the config; keyless
/// DuckDuckGo works with all defaults).
///
/// When [networkGate] is provided, it gates every model-invoked web egress
/// of the web tools (issue #682): `null` — no cube — keeps the requests on
/// the unwrapped client, byte-identical to pre-gate runs.
///
/// When [sqlite] is provided, the `read` tool resolves SQLite database
/// targets (`data.db:table`); without an engine (e.g. web hosts, where FFI
/// is unavailable) such reads return a clean "not supported" note.
///
/// When [lsp] is provided, the `lsp` tool is registered (diagnostics /
/// definition / references / rename backed by a language server). Only
/// process-capable hosts (CLI/desktop) pass it — the process transport
/// factory lives in `lib/io.dart`; web/stub construction leaves the tool
/// out.
///
/// When [config] is provided, the `config` tool is registered (the
/// `check|path|get|set` ops over [ConfigService] — issue #29 S3). Hosts
/// without a config service (tests of individual tools, minimal embeds)
/// leave it out.
///
/// When [mcp] is provided, the tools of currently CONNECTED MCP servers are
/// included (as `mcp__<server>__<tool>`); servers connect in the background
/// after startup, so the host must additionally listen to
/// `McpManager.onChanged` to re-register late arrivals (see `AgentCli`).
///
/// [model] is forwarded to [readFileTool] for the non-vision image note.
List<AgentTool> builtinTools(
  ExecutionEnv env, {
  HashlineSnapshotStore? snapshots,
  WebSearchConfig? webSearch,
  CubeNetworkGate? networkGate,
  ConfigService? config,
  Model? Function()? model,
  SqliteEngine? sqlite,
  LspToolConfig? lsp,
  McpManager? mcp,
  ShellJobRegistry? shellJobs,
  PasswordPromptCallback? onPasswordPrompt,
  RedactionConfig? redactionConfig,
  Set<String> Function()? approvedSecretLiterals,
  Duration shellAutoBackgroundAfter = const Duration(
    seconds: defaultShellAutoBackgroundSeconds,
  ),
}) {
  final store = snapshots ?? HashlineSnapshotStore();
  return [
    readFileTool(env, snapshots: store, model: model, sqlite: sqlite),
    writeFileTool(env),
    editFileTool(env, snapshots: store),
    listDirTool(env),
    shellTool(
      env,
      jobs: shellJobs,
      onPasswordPrompt: onPasswordPrompt,
