  YamlMap node,
) {
  bool? registry;
  int? maxPerRequest;
  int? maxBytesPerRequest;
  Map<String, int>? perModel;
  bool? autoInspect;
  for (final key in node.keys) {
    switch (key) {
      case 'registry':
        registry = _readImagesBool(node, '$key');
