/// Builds the note header of an image read: the `[Image: …]` line plus the
/// conversion, resize-mapping, and non-vision hints (pi's `conversionHint`,
/// `formatDimensionNote`, and `getNonVisionImageNote`).
String _imageNoteHeader(
  String path,
  _InlineImageResult processed,
  Model? Function()? model,
) {
  final note = StringBuffer()
    ..write('[Image: $path, ${processed.width}x${processed.height}');
  if (processed.resized) {
    note.write(
      ', resized to ${processed.outputWidth}x${processed.outputHeight}',
    );
  }
  note.write(']');
  // pi's `conversionHint`.
  final convertedFrom = processed.convertedFrom;
  if (convertedFrom != null && convertedFrom != processed.mimeType) {
    note.write(
      '\n[Image converted from $convertedFrom to ${processed.mimeType}.]',
    );
  }
  // pi's `formatDimensionNote`: coordinate-mapping hint after resize.
  if (processed.resized) {
    final scale = processed.width / processed.outputWidth;
    note.write(
      '\n[Image: original ${processed.width}x${processed.height}, '
      'displayed at ${processed.outputWidth}x${processed.outputHeight}. '
      'Multiply coordinates by ${scale.toStringAsFixed(2)} to map to '
      'original image.]',
    );
  }
  // pi's `getNonVisionImageNote` — the final omission note rides the
  // resolver-driven suffixes below (gh-1984); the ride-in-place path keeps
  // today's shape byte-identically.
  final currentModel = model?.call();
  if (currentModel != null && !currentModel.input.contains('image')) {
    note.write(_nonVisionNoteSuffix());
  }
  return note.toString();
}

/// The text branch of the `read` tool: selector mapping, head truncation
/// with continuation notices, and hashline-mode numbering/recording.
Future<ToolExecutionResult> _readTextContent(
  ExecutionEnv env,
  HashlineSnapshotStore store,
  String path,
  ReadSelector parsed,
  int? offset,
  int? limit,
  String? embedded,
  bool hashlineMode,
  CancelToken? cancelToken,
) async {
  final read = embedded != null
      ? Ok<String, FileError>(embedded)
      : await env.readTextFile(path);
  if (read.isErr) throw StateError('${read.errorOrNull}');
  cancelToken?.throwIfCancelled();

late final Future<void> Function() persistConfig;

// Media slots (gh-1984 AC5/AC8): ONE persisted source for every host —
// the `models:` slots the app and `/models set` write. The explicit
// flags stay the override; without one the persisted slot serves.
// Resolution re-runs per image read via the resolver below, so a
// `/models set` edit (or a key landing in the secure store) applies
// without a restart.
Future<String?> resolveMediaSlotKeyName(String name) async {
  final envValue = Platform.environment[name];
  if (envValue != null && envValue.isNotEmpty) return envValue;
  return keyCache.read(name);
}

/// The effective vision capability: `--vision-model` (the override,
/// hard-failing the boot without a key — unchanged) else the persisted
/// `models.slots.vision`.
Future<InspectImageConfig?> resolveVisionConfig() async {
  if (effective.visionModel != null) {
    return InspectImageConfig(
      modelId: effective.visionModel!,
      baseUrl: effective.visionBaseUrl,
    );
  }
  return resolveVisionSlotInspectConfig(
    saved.models,
    resolveKey: resolveMediaSlotKeyName,
  );
}

/// The effective transcription capability: `--transcribe-model` (the
/// override, unchanged) else the persisted `models.slots.transcription`.
Future<TranscribeAudioConfig?> resolveTranscribeConfig() async {
  if (effective.transcribeModel != null) {
    return TranscribeAudioConfig(
      modelId: effective.transcribeModel!,
      baseUrl: effective.transcribeBaseUrl,
    );
  }
  return resolveTranscriptionSlotConfig(
    saved.models,
    resolveKey: resolveMediaSlotKeyName,
  );
}

final visionConfig = await resolveVisionConfig();
final transcribeConfig = await resolveTranscribeConfig();

// The process's single hub client instance: registered as the `hub`
